# Phase 38: learn vision offline. Frames: 25 random games (2 min, reflexes from labels, USE p=0.1) on MAP01-06,
# 15 on MAP07-15 (frames_mapNN.npz, ~350 MB, not kept). fit3_* : trained on MAP01/03/04; vis12_* : trained on
# MAP01/03/04/07-15; both tested on unseen MAP02/05/06. The agent reads vis12_h128_e3.npz.
V=NNtesting/experiments/td_actor_critic/vision_offline.py
for m in map01 map03 map04 map02 map05 map06; do python3 $V collect --levels $m --games 25 --minutes 2 --seed S --out frames_$m.npz; done  # S = 10, 20, ... per level
for m in map07 map08 map09 map10 map11 map12 map13 map14 map15; do python3 $V collect --levels $m --games 15 --minutes 2 --seed S --out frames_$m.npz; done  # S = 110, 120, ...
python3 $V fit --data frames_map01.npz,...,frames_map15.npz --train map01,map03,map04,map07,map08,map09,map10,map11,map12,map13,map14,map15 --hidden 128 --epochs 3 --out vis12_h128_e3.npz
python3 NNtesting/experiments/td_actor_critic/doom_td.py --arm td --scenario map01 --episodes 1500 --checkpoint 10 --keep_every 100 --set test=10 --set critic_rate=0.1 --set center=0.001 --set actor_rate=0.1 --set trace_every=100 --set features=both_pool --set until_death=5 --set reward_scale=1 --set place=0 --set drives=1 --set hurt_weight=0.05 --set gamma=0.99 --set door_reflex=1 --set boredom=0.01 --set attack_reflex=1 --set orient_reflex=1 --set poke=0.1 --set actor_settle=200 --set consolidate=0.8 --set anchor_at=0.1 --set anchor_pull=0.2 --set restless=150 --set restless_after_exit=1 --set maps=map01,map03,map04 --set test_maps=map02,map05,map06 --set danger=8 --set view_novelty=0.03 --set view_block=5 --set view_radius=0.6 --set vision_model=results/td-actor-critic/doom/vision_offline/vis12_h128_e3.npz --set vision_feed=out --out visout_s1 --seed 1
